          postprocess_concurrency: 'Đồng thời theo tiến trình dành riêng cho việc hoàn tất phân tích nhẹ và phân tán làm giàu. Tối thiểu 1; cần khởi động lại dịch vụ.',
          enrichment_concurrency: 'Đồng thời theo tiến trình được đảm bảo cho việc tạo tóm tắt, hình ảnh, đồ thị và câu hỏi. Giai đoạn làm giàu cũng có thể mượn nhóm đàn hồi dùng chung. Tối thiểu 1; cần khởi động lại dịch vụ.',
          maintenance_concurrency: 'Đồng thời theo tiến trình cho đồng bộ nguồn, xử lý hàng loạt và dọn dẹp, được cách ly hoàn toàn khỏi luồng hướng tới người dùng. Tối thiểu 1; cần khởi động lại dịch vụ.',
          shared_concurrency: 'Đồng thời đàn hồi theo tiến trình được dùng chung bởi phân tích cốt lõi và làm giàu nội dung; bên nào có tồn đọng sẽ tự động mượn. Tối thiểu 1; cần khởi động lại dịch vụ.',
          wiki_concurrency: 'Đồng thời theo tiến trình cho nhóm Worker Wiki chuyên dụng, được cách ly khỏi các tác vụ thượng nguồn. Tối thiểu 1; cần khởi động lại dịch vụ.'
