          self_service_creation_enabled: 'Cho phép người dùng không phải siêu quản trị tự tạo không gian làm việc hay không. Khi tắt, người dùng thường chỉ có thể tham gia không gian làm việc hiện có qua lời mời; siêu quản trị xuyên không gian vẫn được miễn trừ. Có hiệu lực ngay lập tức.',
          default_storage_quota_gb: 'Hạn mức lưu trữ mặc định (GB) được chỉ định khi tạo không gian mới, bao gồm vector, bản gốc, văn bản, chỉ mục và dữ liệu liên quan. Chỉ áp dụng cho các không gian tạo mới. 0 hoặc số âm dùng mặc định 10 GB.',
          auto_create_api_key: 'Tự động tạo API key full_access cho không gian làm việc mới và trả token dạng văn bản thô trong phản hồi tạo. Chỉ dùng cho các tích hợp phụ thuộc hành vi cũ; mặc định tắt và khuyến nghị tạo API key một cách tường minh.',
          auto_accept_invitation: 'Khi bật, việc mời người dùng đã đăng ký qua email sẽ thêm họ làm thành viên ngay lập tức thay vì chờ xác nhận qua hộp thư. Khi tắt, người được mời phải xác nhận từ hộp thư của họ. Có hiệu lực ngay lập tức.'
